import{_ as l,a0 as d,w as o,s as u,I as e,x as n,a1 as p,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Systemd 服务：响应变化 | LCTT x X-CMD","titleTemplate":false,"description":"Systemd 服务：响应变化 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Systemd 服务：响应变化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Systemd 服务：响应变化 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20180612 Systemd Services- Reacting to Change","title":"Systemd 服务：响应变化","tag":"202005","desc":""},"relativePath":"202005/20180612 Systemd Services- Reacting to Change.md","filePath":"[post].md"}'),r={name:"202005/20180612 Systemd Services- Reacting to Change.md"};function m(c,s,g,b,v,k){const a=d("Link");return o(),u("div",null,[s[63]||(s[63]=e("h1",{id:"systemd-服务-响应变化",tabindex:"-1"},[n("Systemd 服务：响应变化 "),e("a",{class:"header-anchor",href:"#systemd-服务-响应变化","aria-label":"Permalink to “Systemd 服务：响应变化”"},"​")],-1)),s[64]||(s[64]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/12/001037iz91uu9b15dqb9w3.jpg",alt:""})],-1)),e("p",null,[p(a,{href:"https://www.intel.com/content/www/us/en/products/boards-kits/compute-stick/stk1a32sc.html"},{default:i(()=>[...s[0]||(s[0]=[n("我有一个这样的电脑棒",-1)])]),_:1}),s[1]||(s[1]=n("（图1），我把它用作通用服务器。它很小且安静，由于它是基于 x86 架构的，因此我为我的打印机安装驱动没有任何问题，而且这就是它大多数时候干的事：与客厅的共享打印机和扫描仪通信。",-1))]),s[65]||(s[65]=e("p",null,[e("img",{src:"https://lcom.static.linuxfound.org/sites/lcom/files/fig01.png",alt:"ComputeStick"})],-1)),s[66]||(s[66]=e("p",null,[e("em",null,"一个英特尔电脑棒。欧元硬币大小。")],-1)),s[67]||(s[67]=e("p",null,"大多数时候它都是闲置的，尤其是当我们外出时，因此我认为用它作监视系统是个好主意。该设备没有自带的摄像头，也不需要一直监视。我也不想手动启动图像捕获，因为这样就意味着在出门前必须通过 SSH 登录，并在 shell 中编写命令来启动该进程。",-1)),s[68]||(s[68]=e("p",null,"因此，我以为应该这么做：拿一个 USB 摄像头，然后只需插入它即可自动启动监视系统。如果这个电脑棒重启后发现连接了摄像头也启动监视系统就更加分了。",-1)),e("p",null,[s[4]||(s[4]=n("在先前的文章中，我们看到 systemd 服务既可以",-1)),p(a,{href:"https://linux.cn/article-9700-1.html"},{default:i(()=>[...s[2]||(s[2]=[n("手动启动或停止",-1)])]),_:1}),s[5]||(s[5]=n("，也可以",-1)),p(a,{href:"https://linux.cn/article-9703-1.html"},{default:i(()=>[...s[3]||(s[3]=[n("在满足某些条件时启动或停止",-1)])]),_:1}),s[6]||(s[6]=n("。这些条件不限于操作系统在启动或关机时序中达到某种状态，还可以在你插入新硬件或文件系统发生变化时进行。你可以通过将 Udev 规则与 systemd 服务结合起来实现。",-1))]),s[69]||(s[69]=t(`<h3 id="有-udev-支持的热插拔" tabindex="-1">有 Udev 支持的热插拔 <a class="header-anchor" href="#有-udev-支持的热插拔" aria-label="Permalink to “有 Udev 支持的热插拔”">​</a></h3><p>Udev 规则位于 <code>/etc/udev/rules</code> 目录中，通常是由导致一个<ruby>动作<rt>action</rt></ruby>的<ruby>条件<rt>conditions</rt></ruby>和<ruby>赋值<rt>assignments</rt></ruby>的单行语句来描述。</p><p>有点神秘。让我们再解释一次：</p><p>通常，在 Udev 规则中，你会告诉 systemd 当设备连接时需要查看什么信息。例如，你可能想检查刚插入的设备的品牌和型号是否与你让 Udev 等待的设备的品牌和型号相对应。这些就是前面提到的“条件”。</p><p>然后，你可能想要更改一些内容，以便以后可以方便使用该设备。例如，更改设备的读写权限：如果插入 USB 打印机，你会希望用户能够从打印机读取信息（用户的打印应用程序需要知道其模型、制造商，以及是否准备好接受打印作业）并向其写入内容，即发送要打印的内容。更改设备的读写权限是通过你之前阅读的“赋值” 之一完成的。</p><p>最后，你可能希望系统在满足上述条件时执行某些动作，例如在插入某个外部硬盘时启动备份程序以复制重要文件。这就是上面提到的“动作”的例子。</p><p>了解这些之后, 来看看以下几点:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;video4linux&quot;, ATTRS{idVendor}==&quot;03f0&quot;, ATTRS{idProduct}==&quot;e207&quot;, </span></span>
<span class="line"><span>SYMLINK+=&quot;mywebcam&quot;, TAG+=&quot;systemd&quot;, MODE=&quot;0666&quot;, ENV{SYSTEMD_WANTS}=&quot;webcam.service&quot;</span></span></code></pre></div><p>规则的第一部分,</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;video4linux&quot;,  ATTRS{idVendor}==&quot;03f0&quot;, </span></span>
<span class="line"><span>ATTRS{idProduct}==&quot;e207&quot; [etc... ]</span></span></code></pre></div><p>表明了执行你想让系统执行的其他动作之前设备必须满足的条件。设备必须被添加到（<code>ACTION==&quot;add&quot;</code>）机器上，并且必须添加到 <code>video4linux</code> 子系统中。为了确保仅在插入正确的设备时才应用该规则，你必须确保 Udev 正确识别设备的制造商（<code>ATTRS{idVendor}==&quot;03f0&quot;</code>）和型号（<code>ATTRS{idProduct}==&quot;e207&quot;</code>）。</p><p>在本例中，我们讨论的是这个设备（图2）：</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/fig02.png?itok=esFv4BdM" alt="webcam" title="webcam"></p><p><em>这个试验使用的是 HP 的摄像头。</em></p><p>注意怎样用 <code>==</code> 来表示这是一个逻辑操作。你应该像这样阅读上面的简要规则：</p><blockquote><p>如果添加了一个设备并且该设备由 video4linux 子系统控制，而且该设备的制造商编码是 03f0，型号是 e207，那么...</p></blockquote><p>但是，你从哪里获取的这些信息？你在哪里找到触发事件的动作、制造商、型号等？你可要使用多个来源。你可以通过将摄像头插入机器并运行 <code>lsusb</code> 来获得 <code>IdVendor</code> 和 <code>idProduct</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsusb</span></span>
<span class="line"><span>Bus 002 Device 002: ID 8087:0024 Intel Corp. Integrated Rate Matching Hub</span></span>
<span class="line"><span>Bus 002 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 004 Device 001: ID 1d6b:0003 Linux Foundation 3.0 root hub</span></span>
<span class="line"><span>Bus 003 Device 003: ID 03f0:e207 Hewlett-Packard</span></span>
<span class="line"><span>Bus 003 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span>
<span class="line"><span>Bus 001 Device 003: ID 04f2:b1bb Chicony Electronics Co., Ltd</span></span>
<span class="line"><span>Bus 001 Device 002: ID 8087:0024 Intel Corp. Integrated Rate Matching Hub</span></span>
<span class="line"><span>Bus 001 Device 001: ID 1d6b:0002 Linux Foundation 2.0 root hub</span></span></code></pre></div><p>我用的摄像头是 HP 的，你在上面的列表中只能看到一个 HP 设备。<code>ID</code> 提供了制造商和型号，它们以冒号（<code>:</code>）分隔。如果你有同一制造商的多个设备，不确定哪个是哪个设备，请拔下摄像头，再次运行 <code>lsusb</code> , 看看少了什么。</p><p>或者...</p><p>拔下摄像头，等待几秒钟，运行命令 <code>udevadmin monitor --environment</code> ，然后重新插入摄像头。当你使用的是HP摄像头时，你将看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>udevadmin monitor --environment</span></span>
<span class="line"><span>UDEV  [35776.495221] add      /devices/pci0000:00/0000:00:1c.3/0000:04:00.0</span></span>
<span class="line"><span>    /usb3/3-1/3-1:1.0/input/input21/event11 (input) </span></span>
<span class="line"><span>.MM_USBIFNUM=00 </span></span>
<span class="line"><span>ACTION=add </span></span>
<span class="line"><span>BACKSPACE=guess </span></span>
<span class="line"><span>DEVLINKS=/dev/input/by-path/pci-0000:04:00.0-usb-0:1:1.0-event </span></span>
<span class="line"><span>     /dev/input/by-id/usb-Hewlett_Packard_HP_Webcam_HD_2300-event-if00 </span></span>
<span class="line"><span>DEVNAME=/dev/input/event11 </span></span>
<span class="line"><span>DEVPATH=/devices/pci0000:00/0000:00:1c.3/0000:04:00.0/</span></span>
<span class="line"><span>     usb3/3-1/3-1:1.0/input/input21/event11 </span></span>
<span class="line"><span>ID_BUS=usb </span></span>
<span class="line"><span>ID_INPUT=1 </span></span>
<span class="line"><span>ID_INPUT_KEY=1 </span></span>
<span class="line"><span>ID_MODEL=HP_Webcam_HD_2300 </span></span>
<span class="line"><span>ID_MODEL_ENC=HPx20Webcamx20HDx202300 </span></span>
<span class="line"><span>ID_MODEL_ID=e207 </span></span>
<span class="line"><span>ID_PATH=pci-0000:04:00.0-usb-0:1:1.0 </span></span>
<span class="line"><span>ID_PATH_TAG=pci-0000_04_00_0-usb-0_1_1_0 </span></span>
<span class="line"><span>ID_REVISION=1020 </span></span>
<span class="line"><span>ID_SERIAL=Hewlett_Packard_HP_Webcam_HD_2300 </span></span>
<span class="line"><span>ID_TYPE=video </span></span>
<span class="line"><span>ID_USB_DRIVER=uvcvideo </span></span>
<span class="line"><span>ID_USB_INTERFACES=:0e0100:0e0200:010100:010200:030000: </span></span>
<span class="line"><span>ID_USB_INTERFACE_NUM=00 </span></span>
<span class="line"><span>ID_VENDOR=Hewlett_Packard </span></span>
<span class="line"><span>ID_VENDOR_ENC=Hewlettx20Packard </span></span>
<span class="line"><span>ID_VENDOR_ID=03f0 </span></span>
<span class="line"><span>LIBINPUT_DEVICE_GROUP=3/3f0/e207:usb-0000:04:00.0-1/button </span></span>
<span class="line"><span>MAJOR=13 </span></span>
<span class="line"><span>MINOR=75 </span></span>
<span class="line"><span>SEQNUM=3162 </span></span>
<span class="line"><span>SUBSYSTEM=input </span></span>
<span class="line"><span>USEC_INITIALIZED=35776495065 </span></span>
<span class="line"><span>XKBLAYOUT=es </span></span>
<span class="line"><span>XKBMODEL=pc105 </span></span>
<span class="line"><span>XKBOPTIONS= </span></span>
<span class="line"><span>XKBVARIANT=</span></span></code></pre></div><p>可能看起来有很多信息要处理，但是，看一下这个：列表前面的 <code>ACTION</code> 字段, 它告诉你刚刚发生了什么事件，即一个设备被添加到系统中。你还可以在其中几行中看到设备名称的拼写，因此可以非常确定它就是你要找的设备。输出里还显示了制造商的ID（<code>ID_VENDOR_ID = 03f0</code>）和型号（<code>ID_VENDOR_ID = 03f0</code>）。</p><p>这为你提供了规则条件部分需要的四个值中的三个。你可能也会想到它还给了你第四个，因为还有一行这样写道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SUBSYSTEM=input</span></span></code></pre></div><p>小心！尽管 USB 摄像头确实是提供输入的设备（键盘和鼠标也是），但它也属于 usb 子系统和其他几个子系统。这意味着你的摄像头被添加到了多个子系统，并且看起来像多个设备。如果你选择了错误的子系统，那么你的规则可能无法按你期望的那样工作，或者根本无法工作。</p><p>因此，第三件事就是检查网络摄像头被添加到的所有子系统，并选择正确的那个。为此，请再次拔下摄像头，然后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls /dev/video*</span></span></code></pre></div><p>这将向你显示连接到本机的所有视频设备。如果你使用的是笔记本，大多数笔记本都带有内置摄像头，它可能会显示为 <code>/dev/video0</code> 。重新插入摄像头，然后再次运行 <code>ls /dev/video*</code>。</p><p>现在，你应该看到多一个视频设备（可能是<code>/dev/video1</code>）。</p><p>现在，你可以通过运行 <code>udevadm info -a /dev/video1</code> 找出它所属的所有子系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>udevadm info -a /dev/video1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Udevadm info starts with the device specified by the devpath and then</span></span>
<span class="line"><span>walks up the chain of parent devices. It prints for every device</span></span>
<span class="line"><span>found, all possible attributes in the udev rules key format.</span></span>
<span class="line"><span>A rule to match, can be composed by the attributes of the device</span></span>
<span class="line"><span>and the attributes from one single parent device.</span></span>
<span class="line"><span></span></span>
<span class="line"><span> looking at device &#39;/devices/pci0000:00/0000:00:1c.3/0000:04:00.0</span></span>
<span class="line"><span>  /usb3/3-1/3-1:1.0/video4linux/video1&#39;:</span></span>
<span class="line"><span> KERNEL==&quot;video1&quot;</span></span>
<span class="line"><span> SUBSYSTEM==&quot;video4linux&quot;</span></span>
<span class="line"><span> DRIVER==&quot;&quot;</span></span>
<span class="line"><span> ATTR{dev_debug}==&quot;0&quot;</span></span>
<span class="line"><span> ATTR{index}==&quot;0&quot;</span></span>
<span class="line"><span> ATTR{name}==&quot;HP Webcam HD 2300: HP Webcam HD&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[etc...]</span></span></code></pre></div><p>输出持续了相当长的时间，但是你感兴趣的只是开头的部分：<code>SUBSYSTEM ==&quot;video4linux&quot;</code>。你可以将这行文本直接复制粘贴到你的规则中。输出的其余部分（为简洁未显示）为你提供了更多的信息，例如制造商和型号 ID，同样是以你可以复制粘贴到你的规则中的格式。</p><p>现在，你有了识别设备的方式吗，并明确了什么事件应该触发该动作，该对设备进行修改了。</p><p>规则的下一部分，<code>SYMLINK+=&quot;mywebcam&quot;, TAG+=&quot;systemd&quot;, MODE=&quot;0666&quot;</code> 告诉 Udev 做三件事：首先，你要创建设备的符号链接（例如 <code>/dev/video1</code> 到 <code>/dev/mywebcam</code>。这是因为你无法预测系统默认情况下会把那个设备叫什么。当你拥有内置摄像头并热插拔一个新的时，内置摄像头通常为 <code>/dev/video0</code>，而外部摄像头通常为 <code>/dev/video1</code>。但是，如果你在插入外部 USB 摄像头的情况下重启计算机，则可能会相反，内部摄像头可能会变成 <code>/dev/video1</code> ，而外部摄像头会变成 <code>/dev/video0</code>。这想告诉你的是，尽管你的图像捕获脚本（稍后将看到）总是需要指向外部摄像头设备，但是你不能依赖它是 <code>/dev/video0</code> 或 <code>/dev/video1</code>。为了解决这个问题，你告诉 Udev 创建一个符号链接，该链接在设备被添加到 <code>video4linux</code> 子系统的那一刻起就不会再变，你将使你的脚本指向该链接。</p><p>第二件事就是将 <code>systemd</code> 添加到与此规则关联的 Udev 标记列表中。这告诉 Udev，该规则触发的动作将由 systemd 管理，即它将是某种 systemd 服务。</p><p>注意在这个两种情况下是如何使用 <code>+=</code> 运算符的。这会将值添加到列表中，这意味着你可以向 <code>SYMLINK</code> 和 <code>TAG</code> 添加多个值。</p>`,37)),e("p",null,[s[8]||(s[8]=n("另一方面，",-1)),s[9]||(s[9]=e("code",null,"MODE",-1)),s[10]||(s[10]=n(" 值只能包含一个值（因此，你可以使用简单的 ",-1)),s[11]||(s[11]=e("code",null,"=",-1)),s[12]||(s[12]=n(" 赋值运算符）。",-1)),s[13]||(s[13]=e("code",null,"MODE",-1)),s[14]||(s[14]=n(" 的作用是告诉 Udev 谁可以读或写该设备。如果你熟悉 ",-1)),s[15]||(s[15]=e("code",null,"chmod",-1)),s[16]||(s[16]=n("（你读到此文, 应该会熟悉），你就也会熟悉",-1)),p(a,{href:"https://chmod-calculator.com/"},{default:i(()=>[...s[7]||(s[7]=[n("如何用数字表示权限",-1)])]),_:1}),s[17]||(s[17]=n("。这就是它的含义：",-1)),s[18]||(s[18]=e("code",null,"0666",-1)),s[19]||(s[19]=n(" 的含义是 “向所有人授予对设备的读写权限”。",-1))]),s[70]||(s[70]=t(`<p>最后， <code>ENV{SYSTEMD_WANTS}=&quot;webcam.service&quot;</code> 告诉 Udev 要运行什么 systemd 服务。</p><p>将此规则保存到 <code>/etc/udev/rules.d</code> 目录名为 <code>90-webcam.rules</code>（或类似的名称）的文件中，你可以通过重启机器或运行以下命令来加载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo udevadm control --reload-rules &amp;&amp; udevadm trigger</span></span></code></pre></div><h3 id="最后是服务" tabindex="-1">最后是服务 <a class="header-anchor" href="#最后是服务" aria-label="Permalink to “最后是服务”">​</a></h3><p>Udev 规则触发的服务非常简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># webcam.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=simple</span></span>
<span class="line"><span>ExecStart=/home/[user name]/bin/checkimage.sh</span></span></code></pre></div>`,6)),e("p",null,[s[21]||(s[21]=n("基本上，它只是运行存储在你个人 ",-1)),s[22]||(s[22]=e("code",null,"bin/",-1)),s[23]||(s[23]=n(" 中的 ",-1)),s[24]||(s[24]=e("code",null,"checkimage.sh",-1)),s[25]||(s[25]=n(" 脚本并将其放到后台。",-1)),p(a,{href:"https://linux.cn/article-9700-1.html"},{default:i(()=>[...s[20]||(s[20]=[n("这是你在先前的文章中看过的内容",-1)])]),_:1}),s[26]||(s[26]=n("。它看起来似乎很小，但那只是因为它是被 Udev 规则调用的，你刚刚创建了一种特殊的 systemd 单元，称为 ",-1)),s[27]||(s[27]=e("code",null,"device",-1)),s[28]||(s[28]=n(" 单元。 恭喜。",-1))]),s[71]||(s[71]=t(`<p>至于 <code>webcam.service</code> 调用的 <code>checkimage.sh</code> 脚本，有几种方法从摄像头抓取图像并将其与前一个图像进行比较以检查变化（这是 <code>checkimage.sh</code> 所做的事），但这是我的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash </span></span>
<span class="line"><span># This is the checkimage.sh script</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mplayer -vo png -frames 1 tv:// -tv driver=v4l2:width=640:height=480:device=</span></span>
<span class="line"><span>    /dev/mywebcam &amp;&gt;/dev/null </span></span>
<span class="line"><span>mv 00000001.png /home/[user name]/monitor/monitor.png </span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true </span></span>
<span class="line"><span>do </span></span>
<span class="line"><span>   mplayer -vo png -frames 1 tv:// -tv driver=v4l2:width=640:height=480:device=/dev/mywebcam &amp;&gt;/dev/null </span></span>
<span class="line"><span>   mv 00000001.png /home/[user name]/monitor/temp.png </span></span>
<span class="line"><span></span></span>
<span class="line"><span>   imagediff=\`compare -metric mae /home/[user name]/monitor/monitor.png /home/[user name]</span></span>
<span class="line"><span>       /monitor/temp.png /home/[user name]/monitor/diff.png 2&gt;&amp;1 &gt; /dev/null | cut -f 1 -d &quot; &quot;\` </span></span>
<span class="line"><span>   if [ \`echo &quot;$imagediff &gt; 700.0&quot; | bc\` -eq 1 ] </span></span>
<span class="line"><span>       then </span></span>
<span class="line"><span>           mv /home/[user name]/monitor/temp.png /home/[user name]/monitor/monitor.png </span></span>
<span class="line"><span>       fi </span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>   sleep 0.5 </span></span>
<span class="line"><span>done</span></span></code></pre></div>`,2)),e("p",null,[s[31]||(s[31]=n("首先使用",-1)),p(a,{href:"https://mplayerhq.hu/design7/news.html"},{default:i(()=>[...s[29]||(s[29]=[n("MPlayer",-1)])]),_:1}),s[32]||(s[32]=n("从摄像头抓取一帧（",-1)),s[33]||(s[33]=e("code",null,"00000001.png",-1)),s[34]||(s[34]=n("）。注意，我们怎样将 ",-1)),s[35]||(s[35]=e("code",null,"mplayer",-1)),s[36]||(s[36]=n(" 指向 Udev 规则中创建的 ",-1)),s[37]||(s[37]=e("code",null,"mywebcam",-1)),s[38]||(s[38]=n(" 符号链接，而不是指向 ",-1)),s[39]||(s[39]=e("code",null,"video0",-1)),s[40]||(s[40]=n(" 或 ",-1)),s[41]||(s[41]=e("code",null,"video1",-1)),s[42]||(s[42]=n("。然后，将图像传输到主目录中的 ",-1)),s[43]||(s[43]=e("code",null,"monitor/",-1)),s[44]||(s[44]=n(" 目录。然后执行一个无限循环，一次又一次地执行相同的操作，但还使用了",-1)),p(a,{href:"https://www.imagemagick.org/script/compare.php"},{default:i(()=>[...s[30]||(s[30]=[n("Image Magick 的 compare 工具",-1)])]),_:1}),s[45]||(s[45]=n("来查看最后捕获的图像与 ",-1)),s[46]||(s[46]=e("code",null,"monitor/",-1)),s[47]||(s[47]=n(" 目录中已有的图像之间是否存在差异。",-1))]),s[72]||(s[72]=t('<p>如果图像不同，则表示摄像头的镜框里某些东西动了。该脚本将新图像覆盖原始图像，并继续比较以等待更多变动。</p><h3 id="插线" tabindex="-1">插线 <a class="header-anchor" href="#插线" aria-label="Permalink to “插线”">​</a></h3><p>所有东西准备好后，当你插入摄像头后，你的 Udev 规则将被触发并启动 <code>webcam.service</code>。 <code>webcam.service</code> 将在后台执行 <code>checkimage.sh</code> ，而 <code>checkimage.sh</code> 将开始每半秒拍一次照。你会感觉到，因为摄像头的 LED 在每次拍照时将开始闪。</p><p>与往常一样，如果出现问题，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl status webcam.service</span></span></code></pre></div><p>检查你的服务和脚本正在做什么。</p><h3 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to “接下来”">​</a></h3><p>你可能想知道：为什么要覆盖原始图像？当然，系统检测到任何动静，你都想知道发生了什么，对吗？你是对的，但是如你在下一部分中将看到的那样，将它们保持原样，并使用另一种类型的 systemd 单元处理图像将更好，更清晰和更简单。</p><p>请期待下一篇。</p><hr>',10)),e("p",null,[s[49]||(s[49]=n("via: ",-1)),p(a,{href:"https://www.linux.com/blog/intro-to-linux/2018/6/systemd-services-reacting-change"},{default:i(()=>[...s[48]||(s[48]=[n("https://www.linux.com/blog/intro-to-linux/2018/6/systemd-services-reacting-change",-1)])]),_:1})]),e("p",null,[s[54]||(s[54]=n("作者：",-1)),p(a,{href:"https://www.linux.com/users/bro66"},{default:i(()=>[...s[50]||(s[50]=[n("Paul Brown",-1)])]),_:1}),s[55]||(s[55]=n(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[51]||(s[51]=[n("lujun9972",-1)])]),_:1}),s[56]||(s[56]=n(" 译者：",-1)),p(a,{href:"https://github.com/messon007"},{default:i(()=>[...s[52]||(s[52]=[n("messon007",-1)])]),_:1}),s[57]||(s[57]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[53]||(s[53]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[60]||(s[60]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[58]||(s[58]=[n("LCTT",-1)])]),_:1}),s[61]||(s[61]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:i(()=>[...s[59]||(s[59]=[n("Linux中国",-1)])]),_:1}),s[62]||(s[62]=n(" 荣誉推出",-1))])])}const y=l(r,[["render",m]]);export{T as __pageData,y as default};
